alter table public.projects add column if not exists problem text;
alter table public.projects add column if not exists built text;
alter table public.projects add column if not exists project_type text;
alter table public.projects add column if not exists role text;
create table if not exists public.contact_messages (id uuid primary key default gen_random_uuid(),name text not null,email text not null check(length(email) between 3 and 320),subject text,message text not null check(length(message) between 1 and 5000),is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.skills (id uuid primary key default gen_random_uuid(),category text not null,name text not null,sort_order integer not null default 0,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.journey (id uuid primary key default gen_random_uuid(),label text,title text not null,description text,sort_order integer not null default 0,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.resumes (id uuid primary key default gen_random_uuid(),label text not null,version text,file_path text not null,published boolean not null default true,created_at timestamptz not null default now());
alter table public.contact_messages enable row level security; alter table public.skills enable row level security; alter table public.journey enable row level security; alter table public.resumes enable row level security;
drop policy if exists "public insert contact messages" on public.contact_messages; create policy "public insert contact messages" on public.contact_messages for insert to anon,authenticated with check(length(name) between 1 and 120 and length(message) between 1 and 5000);
drop policy if exists "admin contact messages" on public.contact_messages; create policy "admin contact messages" on public.contact_messages for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public read skills" on public.skills; create policy "public read skills" on public.skills for select using(published or public.is_admin());
drop policy if exists "admin skills" on public.skills; create policy "admin skills" on public.skills for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public read journey" on public.journey; create policy "public read journey" on public.journey for select using(published or public.is_admin());
drop policy if exists "admin journey" on public.journey; create policy "admin journey" on public.journey for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public read resume" on public.resumes; create policy "public read resume" on public.resumes for select using(published or public.is_admin());
drop policy if exists "admin resume" on public.resumes; create policy "admin resume" on public.resumes for all using(public.is_admin()) with check(public.is_admin());
